// JAH demo program — Runtime speedup model
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function jobTime(nCircuits, queueS, runS){ return nCircuits*(queueS+runS); }
function runtimeTime(nCircuits, runS){ return 5+nCircuits*runS; } // one queue wait
check("100 circuits, 60s queue, 2s run: jobs", jobTime(100,60,2), 6200);
check("runtime model", Math.round(runtimeTime(100,2)), 205);
check("~30x faster", Math.round(jobTime(100,60,2)/runtimeTime(100,2)), 30);
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

